figure(1) %[output:63df4ac3]
x1 = linspace(0, 4, 81);
plot(x1, x1, x1, x1.^2, x1, x1.^3) %[output:63df4ac3]
grid on %[output:63df4ac3]
xlabel('x') %[output:63df4ac3]
ylabel('f_1(x) = x; f_2(x) = x^2; f_3(x) = x^3') %[output:63df4ac3]
title('Graphs of the functions xn') %[output:63df4ac3]
legend('f_1(x) = x', 'f_2(x) = x^2', 'f_3(x) = x^3') %[output:63df4ac3]

figure(2) %[output:533e8b54]
subplot(1, 2, 1) %[output:533e8b54]
x2 = 0:pi/40:10*pi;
y = sin(x2).*cos(x2);
z = cos(x2);
plot3(x2, y, z) %[output:533e8b54]
grid on %[output:533e8b54]
xlabel('x') %[output:533e8b54]
ylabel('y(x)') %[output:533e8b54]
zlabel('z(x)') %[output:533e8b54]
title('3D Plot') %[output:533e8b54]

subplot(1, 2, 2) %[output:533e8b54]
polarplot(x2, y) %[output:533e8b54]
title('Polar Plot') %[output:533e8b54]

figure(3) %[output:12eaad5d]
t = linspace(0, 4*pi, 100);
sig_orig = sin(t) + 0.25*randn(1, 100);
sig_filt = smoothdata(sig_orig, 'gaussian', 10);

subplot(1, 2, 1) %[output:12eaad5d]
plot(t, sig_orig, '--', 'LineWidth', 1.5) %[output:12eaad5d]
hold on %[output:12eaad5d]
plot(t, sig_filt, ':', 'LineWidth', 1.5) %[output:12eaad5d]
yline(0.6, '-', 'Color', [0.5 0 0.5], 'LineWidth', 1.5) %[output:12eaad5d]
yline(-0.6, 'k-', 'LineWidth', 1.5) %[output:12eaad5d]
hold off %[output:12eaad5d]
grid on %[output:12eaad5d]
xlabel('Time') %[output:12eaad5d]
ylabel('Voltage') %[output:12eaad5d]
title('Original and Filtered Signals', 'Color', [0.5 0 0.5], 'FontSize', 16) %[output:12eaad5d]
legend('Original', 'Filtered', 'U1', 'U2') %[output:12eaad5d]

subplot(1, 2, 2) %[output:12eaad5d]
idx = sig_orig > 0.6;
stem(t(idx), sig_orig(idx)) %[output:12eaad5d]
hold on %[output:12eaad5d]
[max_v, max_i] = max(sig_orig);
[min_v, min_i] = min(sig_orig);
plot(t(max_i), max_v, 'c*', 'MarkerSize', 8) %[output:12eaad5d]
plot(t(min_i), min_v, 'r*', 'MarkerSize', 8) %[output:12eaad5d]
hold off %[output:12eaad5d]
grid on %[output:12eaad5d]
xlabel('Time') %[output:12eaad5d]
ylabel('Voltage') %[output:12eaad5d]
title('Signal > U1 and Extrema', 'Color', [0.5 0 0.5], 'FontSize', 16) %[output:12eaad5d]
legend('Signal > U1', 'Max', 'Min') %[output:12eaad5d]














